source.script:
var app = Application.currentApplication(); app.includeStandardAdditions = true;
var env = 'export PATH="$HOME/Library/Android/sdk/emulator:$HOME/Library/Android/sdk/platform-tools:/opt/homebrew/bin:/usr/local/bin:/usr/bin:/bin"; ';
function sh(c) { try { return app.doShellScript(env + c); } catch (e) { return ''; } }
function lines(t) { return t.split(/[\r\n]+/).filter(function (l) { return l.trim() !== ''; }); }
var ios = [];
try {
  var list = JSON.parse(app.doShellScript('/usr/bin/xcrun simctl list devices available -j')).devices;
  Object.keys(list).forEach(function (runtime) {
    var m = runtime.match(/SimRuntime\.(\w+)-(.+)$/);
    var system = m ? m[1] + ' ' + m[2].replace(/-/g, '.') : runtime;
    list[runtime].forEach(function (d) {
      ios.push(face({ name: d.name, udid: d.udid, system: system }, d.state === 'Booted'));
    });
  });
} catch (e) {}
function face(d, on) {
  d.state = on ? 'Ligado' : 'Desligado';
  d.symbol = on ? 'stop.fill' : 'play.fill';
  d.hint = on ? 'Encerrar' : 'Iniciar';
  d.doing = on ? 'Encerrando…' : 'Iniciando…';
  d.done = on ? 'encerrado' : 'iniciado';
  return d;
}
var running = {};
lines(sh('adb devices')).forEach(function (l) {
  var m = l.match(/^(emulator-\d+)\s+device/);
  if (m) { var n = lines(sh('adb -s ' + m[1] + ' emu avd name'))[0]; if (n) running[n.trim()] = m[1]; }
});
var android = lines(sh('emulator -list-avds')).filter(function (l) { return !/^(INFO|WARNING|ERROR)\b/.test(l) && l.indexOf('|') < 0; }).map(function (n) {
  n = n.trim();
  return face({ name: n, serial: running[n] || '' }, !!running[n]);
});
var on = ios.concat(android).filter(function (d) { return d.state === 'Ligado'; }).length;
JSON.stringify({ ios: ios, android: android, ligados: on })

run.script:
var app = Application.currentApplication(); app.includeStandardAdditions = true;
var on = '{{state}}' === 'Ligado';
app.doShellScript(on
  ? "/usr/bin/xcrun simctl shutdown '{{udid}}'"
  : "/usr/bin/xcrun simctl boot '{{udid}}' 2>/dev/null; /usr/bin/open -a Simulator");
'ok'

var app = Application.currentApplication(); app.includeStandardAdditions = true;
var on = '{{state}}' === 'Ligado';
app.doShellScript("export PATH=\"$HOME/Library/Android/sdk/emulator:$HOME/Library/Android/sdk/platform-tools:/opt/homebrew/bin:/usr/local/bin:/usr/bin:/bin\"; " + (on
  ? "adb -s '{{serial}}' emu kill"
  : "nohup emulator -avd '{{name}}' >/dev/null 2>&1 &"));
'ok'
